        return self.expr()

    def next_char(self):
        if self.position < self.length:
            char = self.expression[self.position]
            self.position += 1
            return char
        return None

    def expr(self):
        result = self.term()
        while self.current_char in ('+', '-'):
            if self.current_char == '+':
                self.current_char = self.next_char()
                result += self.term()
            elif self.current_char == '-':
                self.current_char = self.next_char()
                result -= self.term()
        return result

    def term(self):
        result = self.factor()
        while self.current_char in ('*', '/'):
            if self.current_char == '*':
