                result *= self.factor()
            elif self.current_char == '/':
                self.current_char = self.next_char()
                divisor = self.factor()
                if divisor == 0:
                    raise ZeroDivisionError("division by zero")
                result /= divisor
        return result

    def factor(self):
        if self.current_char is None:
            raise Exception("Unexpected end of expression")

